Here's a modern MSTest approach for testing `DataFetcher`:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    [TestMethod]
    public async Task FetchAsync_ReturnsContent_WhenRequestSucceeds()
    {
        var handler = new MockHttpMessageHandler("hello", HttpStatusCode.OK);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        string result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("hello", result);
    }

    [TestMethod]
    public async Task FetchAsync_Throws_WhenStatusCodeIsError()
    {
        var handler = new MockHttpMessageHandler("", HttpStatusCode.InternalServerError);
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            () => fetcher.FetchAsync("https://example.com"));
    }

    [TestMethod]
    public async Task FetchAsync_Throws_WhenCancelled()
    {
        var handler = new MockHttpMessageHandler("ok", HttpStatusCode.OK, delay: TimeSpan.FromSeconds(5));
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    [TestMethod]
    [Timeout(5000)] // safety net — fail fast if test hangs
    public async Task FetchAsync_RespectsTimeout()
    {
        var handler = new MockHttpMessageHandler("ok", HttpStatusCode.OK, delay: TimeSpan.FromSeconds(30));
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);
        using var cts = new CancellationTokenSource(TimeSpan.FromMilliseconds(50));

        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    // Reusable fake handler — no mocking library needed
    private sealed class MockHttpMessageHandler(
        string content, HttpStatusCode statusCode, TimeSpan delay = default)
        : HttpMessageHandler
    {
        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            if (delay > TimeSpan.Zero)
                await Task.Delay(delay, cancellationToken);

            return new HttpResponseMessage(statusCode)
            {
                Content = new StringContent(content)
            };
        }
    }
}
```

**Key modern MSTest patterns used:**

| Pattern | Detail |
|---------|--------|
| `async Task` test methods | MSTest natively awaits them — no `.Result` or `.GetAwaiter()` needed |
| `Assert.ThrowsExactlyAsync` | MSTest v3+ preferred over `ThrowsExceptionAsync` (exact type match) |
| `[Timeout(ms)]` | Per-test safety net so a broken await doesn't hang CI indefinitely |
| `CancellationToken` propagation | Tests prove the token is actually forwarded to `HttpClient` |
| Custom `HttpMessageHandler` | Avoids mocking frameworks; gives full control over HTTP behavior |

**Tips:**
- Use `[Timeout]` on any test that touches I/O or delays — it's a CI safeguard, not a functional assertion.
- Prefer `Assert.ThrowsExactlyAsync<T>` (MSTest v3/v4) over the older `Assert.ThrowsExceptionAsync<T>` which also matches derived types.
- Always pass `CancellationToken` through in production code and verify it in tests — this catches a common bug where tokens are accidentally dropped.
